      "title" => struct.title,
      "ttl" => struct.ttl,
      "units" => Units.to_map(struct.units),
      "wind" => Wind.to_map(struct.wind),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule Results do
  @enforce_keys [:channel]
  defstruct [:channel]

  @type t :: %__MODULE__{
          channel: Channel.t()
        }

  def from_map(m) do
    %Results{
      channel: Channel.from_map(m["channel"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "channel" => Channel.to_map(struct.channel),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule Query do
  @enforce_keys [:count, :created, :lang, :results]
  defstruct [:count, :created, :lang, :results]

  @type t :: %__MODULE__{
          count: integer(),
          created: String.t(),
          lang: String.t(),
          results: Results.t()
        }

  def decode_count(value) when is_integer(value), do: value
  def decode_count(_), do: {:error, "Unexpected type when decoding Query.count"}

  def encode_count(value) when is_integer(value), do: value
  def encode_count(_), do: {:error, "Unexpected type when encoding Query.count"}

  def decode_created(value) when is_binary(value), do: value
  def decode_created(_), do: {:error, "Unexpected type when decoding Query.created"}

  def encode_created(value) when is_binary(value), do: value
  def encode_created(_), do: {:error, "Unexpected type when encoding Query.created"}

  def decode_lang(value) when is_binary(value), do: value
  def decode_lang(_), do: {:error, "Unexpected type when decoding Query.lang"}

  def encode_lang(value) when is_binary(value), do: value
  def encode_lang(_), do: {:error, "Unexpected type when encoding Query.lang"}

  def from_map(m) do
    %Query{
      count: decode_count(m["count"]),
      created: decode_created(m["created"]),
      lang: decode_lang(m["lang"]),
      results: Results.from_map(m["results"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "count" => struct.count,
      "created" => struct.created,
      "lang" => struct.lang,
      "results" => Results.to_map(struct.results),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

